bool needsTurning = false;
void change_orientation(double sx, double sy, double dx, double dy) {
    double cos_alpha, alpha, theta, delta;
    double AC, AB;
    bool turnLeft;

    AC = pt_dist(sx, dx, sy, sy);
    AB = pt_dist(sx, dx, sy, dy);

    // Avoid division by zero if start and destination are the same
    if (AB == 0) {
        return;
    }

    cos_alpha = AC / AB;
    alpha = acos(cos_alpha); // Result is in radians

    // Corrected: ort is already in degrees, just copy it to theta
    theta = ort;

    delta = 0.0;
    turnLeft = false;

    // Calculate the target angle based on the quadrant
    if (dx &gt;= sx &amp;&amp; dy &gt;= sy) { // 1st Quadrant
        alpha = alpha * (180 / PI);
        if (alpha &gt; theta) { delta = alpha - theta; turnLeft = true; }
        else { delta = theta - alpha; turnLeft = false; }
    }
    else if (dx &gt;= sx &amp;&amp; dy &lt;= sy) { // 2nd Quadrant
        alpha = -alpha * (180 / PI);
        if (theta &lt; alpha) { delta = alpha - theta; turnLeft = true; }
        else { delta = theta - alpha; turnLeft = false; }
    }
    else if (dx &lt;= sx &amp;&amp; dy &lt;= sy) { // 3rd Quadrant
        alpha = -(180 - alpha * (180 / PI));
        if (theta &lt; alpha) { delta = alpha - theta; turnLeft = true; }
        else { delta = theta - alpha; turnLeft = false; }
    }
    else if (dx &lt;= sx &amp;&amp; dy &gt;= sy) { // 4th Quadrant
        alpha = 180 - alpha * (180 / PI);
        if (theta &lt; alpha) { delta = alpha - theta; turnLeft = true; }
        else { delta = theta - alpha; turnLeft = false; }
    }

    needsTurning = delta &gt; 0.0;

    // Update orientation strictly in degrees
    if (needsTurning &amp;&amp; turnLeft) {
        ort = ort + delta;
    }
    else if (needsTurning &amp;&amp; !turnLeft) {
        ort = ort - delta;
    }
}

point curr, dest;

void plan_traj() {
    int i, j, next_inters = -1;
    int neigh[5] = {-1,-1,-1,-1,-1};
    int k = 0;
    double dist, min_dist;
    bool visited[N_I] = {false,false,false,false,false,false,false,false,false}; // Layout 1
    //bool visited[N_I] = {false,false,false,false,false,false,false,false,false,false,false,false,false,false,false,false,false,false,false,false};  // Layout 2
    bool close;

    curr[0] = robPositionX[id-1];
    curr[1] = robPositionY[id-1];

    // Follow Logic (Keep original target selection)
    if (human_to_be_followed[id-1] == 0 &amp;&amp; robot_to_be_followed[id-1] != 0 &amp;&amp; robot_to_be_followed[id-1] != id) {
        dest[0] = robPositionX[robot_to_be_followed[id-1]-1];
        dest[1] = robPositionY[robot_to_be_followed[id-1]-1]; // Fixed Y coordinate index
    }
    if (human_to_be_followed[id-1] != 0 &amp;&amp; robot_to_be_followed[id-1] == 0) {
        dest[0] = humanPositionX[human_to_be_followed[id-1]-1];
        dest[1] = humanPositionY[human_to_be_followed[id-1]-1];
    }

    // Reset trajectory
    for (i = 0; i &lt; N_P; i++) {
        traj[i][0] = 0.0;
        traj[i][1] = 0.0;
    }
    i = 0;
    curr_traj = 0;

    // Build path among adjacent areas
    close = same_area(curr[0], curr[1], dest[0], dest[1]);
    while (!close) {
        for (j = 0; j &lt; N_I &amp;&amp; k &lt; 3; j++) {
            if (same_area(curr[0], curr[1], INTERSECTIONS[j][0], INTERSECTIONS[j][1]) &amp;&amp; !visited[j]) {
                neigh[k] = j;
                k++;
            }
        }
        if (neigh[0] == -1) {
            close = true;
        } else {
            min_dist = pt_dist(INTERSECTIONS[neigh[0]][0], dest[0], INTERSECTIONS[neigh[0]][1], dest[1]);
            next_inters = neigh[0];
            for (j = 1; j &lt; 5 &amp;&amp; neigh[j] != -1; j++) {
                dist = pt_dist(INTERSECTIONS[neigh[j]][0], dest[0], INTERSECTIONS[neigh[j]][1], dest[1]);
                if (dist &lt; min_dist) {
                    min_dist = dist;
                    next_inters = neigh[j];
                }
            }
            if (i == N_P - 1 || next_inters == -1) return;

            visited[next_inters] = true;
            traj[i][0] = INTERSECTIONS[next_inters][0];
            traj[i][1] = INTERSECTIONS[next_inters][1];
            curr[0] = INTERSECTIONS[next_inters][0];
            curr[1] = INTERSECTIONS[next_inters][1];

            i++;
            next_inters = -1;
            k = 0;
            for(j=0; j&lt;5; j++) neigh[j] = -1;
            close = same_area(curr[0], curr[1], dest[0], dest[1]);
        }
    }
    traj[i][0] = dest[0];
    traj[i][1] = dest[1];

    change_orientation(robPositionX[id-1], robPositionY[id-1], traj[0][0], traj[0][1]);
}

void update_pos(double coeff) {
    double nextX = robPositionX[id-1] + coeff*Tpoll*cos(ort*PI/180);
    double nextY = robPositionY[id-1] + coeff*Tpoll*sin(ort*PI/180);

    // Collision avoidance with layout boundaries
    if (isValidPosition(nextX, nextY)) {
        robPositionX[id-1] = nextX;
        robPositionY[id-1] = nextY;
    }
}

void initRobot() {
    t = 0;
    V = 0;

    // Fetch the correct X and Y coordinates from the INTERSECTIONS array
    // using the start_nodes index for each specific robot
    robPositionX[id-1] = INTERSECTIONS[R_start_nodes[id-1]][0];
    robPositionY[id-1] = INTERSECTIONS[R_start_nodes[id-1]][1];

    tUpd = 0;
    v_max = fint(_v_max);
    a_max = fint(_a_max);
}

void varsUpdate(double coeff) {
    double final_X;
    double final_Y;

    tUpd = 0;

    // Arrival check to avoid Zeno behavior
    // Re-calculating current target position
    if (human_to_be_followed[id-1] == 0 &amp;&amp; robot_to_be_followed[id-1] != 0) {
        final_X = robPositionX[robot_to_be_followed[id-1]-1];
        final_Y = robPositionY[robot_to_be_followed[id-1]-1];
    } else {
        final_X = humanPositionX[human_to_be_followed[id-1]-1];
        final_Y = humanPositionY[human_to_be_followed[id-1]-1];
    }

    if (robPositionX[id-1] == final_X &amp;&amp; robPositionY[id-1] == final_Y) {
        return;
    }

    if (curr_traj &gt;= N_P || (traj[curr_traj][0]==0.0 &amp;&amp; traj[curr_traj][1]==0.0)) return;

    // Waypoint management with Snap
    if (pt_dist(robPositionX[id-1], traj[curr_traj][0], robPositionY[id-1], traj[curr_traj][1]) &lt; v_max*1.1) {
        robPositionX[id-1] = traj[curr_traj][0];
        robPositionY[id-1] = traj[curr_traj][1];
        curr_traj++;

        if (curr_traj &gt;= N_P || (traj[curr_traj][0]==0.0 &amp;&amp; traj[curr_traj][1]==0.0)) {
            plan_traj();
        } else {
            change_orientation(robPositionX[id-1], robPositionY[id-1], traj[curr_traj][0], traj[curr_traj][1]);
        }
    } else {
        update_pos(coeff);
    }
}
